PRAGMA foreign_keys=ON;
CREATE TABLE "products" ("product_id" TEXT, "sku" TEXT, "name" TEXT, "category" TEXT, "size" TEXT, "price_inr" INTEGER, "cogs_inr" INTEGER, "assumed_fulfilment_payment_cost_inr" INTEGER, "stock" INTEGER, "default_interval_days" INTEGER, PRIMARY KEY ("product_id"));
CREATE TABLE "customers" ("customer_id" TEXT, "shopify_customer_id" TEXT, "name" TEXT, "city" TEXT, "demo_phone" TEXT, "demo_email" TEXT, "whatsapp_consent" INTEGER, "voice_consent" INTEGER, PRIMARY KEY ("customer_id"));
CREATE TABLE "orders" ("order_id" TEXT, "shopify_order_id" TEXT, "customer_id" TEXT, "created_at" TEXT, "day_offset" INTEGER, "payment_method" TEXT, "financial_status" TEXT, "fulfilment_status" TEXT, "order_status" TEXT, "subtotal_inr" INTEGER, "discount_inr" INTEGER, "shipping_inr" INTEGER, "tax_inr" INTEGER, "order_total_inr" INTEGER, "collected_inr" INTEGER, "refunded_inr" INTEGER, "retained_net_sales_inr" INTEGER, "contribution_inr" INTEGER, "source" TEXT, "attributed_campaign" TEXT, PRIMARY KEY ("order_id"), FOREIGN KEY ("customer_id") REFERENCES "customers"("customer_id"));
CREATE TABLE "order_items" ("line_item_id" TEXT, "order_id" TEXT, "product_id" TEXT, "quantity" INTEGER, "unit_price_inr" INTEGER, "line_subtotal_inr" INTEGER, PRIMARY KEY ("line_item_id"), FOREIGN KEY ("order_id") REFERENCES "orders"("order_id"), FOREIGN KEY ("product_id") REFERENCES "products"("product_id"));
CREATE TABLE "bundle_components" ("bundle_product_id" TEXT, "component_product_id" TEXT, "quantity" INTEGER, PRIMARY KEY ("bundle_product_id","component_product_id"), FOREIGN KEY ("bundle_product_id") REFERENCES "products"("product_id"), FOREIGN KEY ("component_product_id") REFERENCES "products"("product_id"));
CREATE TABLE "razorpay_signals" ("customer_id" TEXT, "source" TEXT, "matched" INTEGER, "risk_tier" TEXT, "payment_preference" TEXT, "confidence" TEXT, "as_of" TEXT, "risk_reason" TEXT, PRIMARY KEY ("customer_id"), FOREIGN KEY ("customer_id") REFERENCES "customers"("customer_id"));
CREATE TABLE "contacts" ("contact_id" TEXT, "customer_id" TEXT, "contacted_at" TEXT, "day_offset" INTEGER, "channel" TEXT, "type" TEXT, "source" TEXT, PRIMARY KEY ("contact_id"), FOREIGN KEY ("customer_id") REFERENCES "customers"("customer_id"));
CREATE TABLE "refunds" ("refund_id" TEXT, "order_id" TEXT, "customer_id" TEXT, "status" TEXT, "amount_inr" INTEGER, "reason" TEXT, "source" TEXT, PRIMARY KEY ("refund_id"), FOREIGN KEY ("order_id") REFERENCES "orders"("order_id"), FOREIGN KEY ("customer_id") REFERENCES "customers"("customer_id"));
CREATE TABLE "monthly_summary" ("period_start" TEXT, "period_end" TEXT, "orders" INTEGER, "customers" INTEGER, "retained_net_sales_inr" INTEGER, "cod_orders" INTEGER, "rto_orders" INTEGER, "returned_orders" INTEGER, PRIMARY KEY ("period_start"));
CREATE TABLE "benchmark_results" ("assumed_response_multiplier" REAL, "strategy" TEXT, "audience" INTEGER, "contacts" INTEGER, "purchases" INTEGER, "collectedOrders" INTEGER, "netSales" INTEGER, "merchantContribution" INTEGER, "operatorCost" REAL, "incremental" INTEGER, "successFee" REAL, "merchantRetains" REAL, "operatorContribution" REAL);
CREATE INDEX "idx_orders_customer_id" ON "orders"("customer_id");
CREATE INDEX "idx_order_items_order_id" ON "order_items"("order_id");
CREATE INDEX "idx_contacts_customer_id" ON "contacts"("customer_id");
